            }});
            const fresh = await codemode.wit.open({{
              repo: "owner/repo", ref: "main", freshness: "require_fresh"
            }});
            const freshRead = await codemode.wit.read({{
              snapshot_id: fresh.snapshot_id, path: "README.md", start_line: 1, end_line: 1,
              max_bytes: 4096
            }});
            return {{ oldRead, fresh, freshRead }};
            "#,
            serde_json::to_string(&snapshot_id)?
        ),
    )
    .await?;
    assert_eq!(replay["oldRead"]["items"][0]["text"], "alpha");
    assert_eq!(replay["oldRead"]["items"][0]["commit_sha"], original_sha);
    assert_eq!(replay["fresh"]["commit_sha"], moved_sha);
    assert_eq!(
        replay["freshRead"]["items"][0]["text"],
        "changed after snapshot"
    );

    client.cancel().await?;
    Ok(())
}

#[tokio::test]
async fn shipped_code_mode_exhausts_list_and_search_cursors_stably() -> anyhow::Result<()> {
    let temp = tempfile::tempdir()?;
    let cache = temp.path().join("cache");
    std::fs::create_dir(&cache)?;
    let fixture = seed_cached_repo(&cache)?;
    let client = start_code_client(temp.path(), Some((&cache, &fixture.git_config))).await?;
    let source = r#"
        const opened = await codemode.wit.open({ repo: "owner/repo" });
        const listed = [];
        let listCursor;
        let listFinal;
        do {
          const page = await codemode.wit.list({
            snapshot_id: opened.snapshot_id, depth: 3, max_items: 1, max_bytes: 4096,
            ...(listCursor ? { cursor: listCursor } : {})
          });
          listed.push(...page.items.map(item => item.path));
          listFinal = { has_more: page.has_more, next_cursor: page.next_cursor ?? null };
          listCursor = page.next_cursor;
        } while (listCursor);
        const searched = [];
        let searchCursor;
        let searchFinal;
        do {
          const page = await codemode.wit.searchCode({
            snapshot_id: opened.snapshot_id, queries: ["alpha|beta|gamma"], globs: ["README.md"],
            max_results: 1, max_bytes: 4096,
            ...(searchCursor ? { cursor: searchCursor } : {})
          });
          searched.push(...page.items.map(item => `${item.path}:${item.match_line}:${item.query}`));
          searchFinal = { has_more: page.has_more, next_cursor: page.next_cursor ?? null };
          searchCursor = page.next_cursor;
        } while (searchCursor);
        return { listed, listFinal, searched, searchFinal };
    "#;
    let first = call_code_success(&client, source).await?;
    let second = call_code_success(&client, source).await?;
    assert_eq!(first, second);
    assert_eq!(
        first["listFinal"],
        json!({ "has_more": false, "next_cursor": null })
    );
    assert_eq!(
        first["searchFinal"],
        json!({ "has_more": false, "next_cursor": null })
    );
    assert_eq!(
        first["searched"],
        json!([
            "README.md:1:alpha|beta|gamma",
            "README.md:2:alpha|beta|gamma",
            "README.md:3:alpha|beta|gamma"
        ])
    );
    for key in ["listed", "searched"] {
        let values = first[key].as_array().unwrap();
        let unique = values.iter().collect::<std::collections::HashSet<_>>();
        assert_eq!(values.len(), unique.len(), "{key} contains duplicates");
    }
    client.cancel().await?;
    Ok(())
}

#[tokio::test]
async fn shipped_code_mode_enforces_host_concurrency_and_byte_budgets() -> anyhow::Result<()> {
    let temp = tempfile::tempdir()?;
    let cache = temp.path().join("cache");
    std::fs::create_dir(&cache)?;
    let fixture = seed_cached_repo(&cache)?;
    let client = start_code_client(temp.path(), Some((&cache, &fixture.git_config))).await?;

    let concurrency = call_code_success(
        &client,
        r#"
        const opened = await codemode.wit.open({ repo: "owner/repo" });
        const results = await Promise.all(Array.from({ length: 5 }, async () => {
          try {
            await codemode.wit.read({ snapshot_id: opened.snapshot_id, path: "README.md", start_line: 1, end_line: 1 });
            return "ok";
          } catch (error) { return error.code; }
        }));
        return results;
        "#,
    )
    .await?;
    assert!(
        concurrency
            .as_array()
            .unwrap()
            .iter()
            .any(|code| code == "host_concurrency_limit")
    );

    let per_call = call_code_success(
        &client,
        r#"/* wit-adversarial:per-call-bytes */
        const opened = await codemode.wit.open({ repo: "owner/repo" });
        try {
          await codemode.wit.read({ snapshot_id: opened.snapshot_id, path: "medium.txt", start_line: 1, end_line: 1, max_bytes: 4096 });
        } catch (error) { return error.code; }
        return "missing-error";
        "#,
    )
    .await?;
    assert_eq!(per_call, "host_result_bytes_limit");

    let cumulative = call_code_success(
        &client,
        r#"/* wit-adversarial:cumulative-bytes */
        const opened = await codemode.wit.open({ repo: "owner/repo" });
        const codes = [];
        for (let index = 0; index < 3; index += 1) {
          try {
            await codemode.wit.read({ snapshot_id: opened.snapshot_id, path: "medium.txt", start_line: 1, end_line: 1, max_bytes: 4096 });
          } catch (error) { codes.push(error.code); }
        }
        return codes;
        "#,
    )
    .await?;
    assert!(
        cumulative
            .as_array()
            .unwrap()
            .iter()
            .any(|code| code == "cumulative_host_bytes_limit")
    );
    assert_eq!(
        call_code_success(&client, "return 'after-host-limits';").await?,
        "after-host-limits"
    );
    client.cancel().await?;
    Ok(())
}

#[tokio::test]
async fn shipped_code_mode_contains_failures_and_recovers_without_temp_leaks() -> anyhow::Result<()>
{
    let temp = tempfile::tempdir()?;
    let scratch = temp.path().join("scratch");
    std::fs::create_dir(&scratch)?;
    let pid_log = temp.path().join("worker-pids");
    let client = start_code_client_with_pid_log(&scratch, None, &pid_log).await?;

    for (source, accepted_codes) in [
        ("throw new Error('boom');", &["code_rejected"][..]),
        (
            "function recurse() { return recurse(); } return recurse();",
            &["code_rejected", "worker_exited", "deadline_exceeded"][..],
        ),
        (
            "const held = []; while (true) held.push(new ArrayBuffer(1024 * 1024));",
            &["code_rejected", "worker_exited", "deadline_exceeded"][..],
        ),
        (
            "return 'x'.repeat(60 * 1024);",
            &["final_result_bytes_limit"][..],
        ),
    ] {
        let result = call_code(&client, source).await?;
        assert_eq!(
            result.is_error,
            Some(true),
            "source unexpectedly succeeded: {source}"
        );
        let code = result
            .structured_content
            .as_ref()
            .and_then(|value| value["code"].as_str());
        assert!(
            code.is_some_and(|code| accepted_codes.contains(&code)),
            "unexpected failure for {source}: {:?}",
            result.structured_content
        );
        assert_eq!(
            call_code_success(&client, "return 'recovered';").await?,
            "recovered"
        );
        wait_for_empty_directory(&scratch).await?;
    }

    let exhausted = call_code_success(
        &client,
        r#"
        const codes = [];
        for (let i = 0; i < 17; i += 1) {
          try { await codemode.wit.read({}); }
          catch (error) { codes.push(error.code); }
        }
        return codes;
        "#,
    )
    .await?;
    let exhausted = exhausted.as_array().unwrap();
    assert!(exhausted.iter().any(|code| code == "pages_limit"));
    assert!(exhausted.iter().any(|code| code == "host_calls_limit"));
    let uncaught_limit = call_code(
        &client,
        "for (let i = 0; i < 17; i += 1) { try { await codemode.wit.read({}); } catch (error) { if (error.code === 'host_calls_limit') throw error; } } return null;",
    )
    .await?;
    assert_eq!(uncaught_limit.is_error, Some(true));
    assert_eq!(
        uncaught_limit.structured_content.unwrap()["code"],
        "host_calls_limit"
    );
    assert_eq!(
        call_code_success(&client, "return 'after-limits';").await?,
        "after-limits"
    );
    wait_for_empty_directory(&scratch).await?;

    let oversized_source = " ".repeat(wit_quickjs_spike::MAX_SCRIPT_BYTES + 1);
    assert_eq!(
        call_code(&client, &oversized_source)
            .await?
            .structured_content
            .unwrap()["code"],
        "source_bytes_limit"
    );
    assert_eq!(
        call_code_success(&client, "return 'after-source-limit';").await?,
        "after-source-limit"
    );

    let timeout = call_code(&client, "while (true) {}").await?;
    assert_eq!(timeout.is_error, Some(true));
    let timeout_content = timeout.structured_content.unwrap();
    assert_eq!(
        timeout_content["code"], "deadline_exceeded",
        "unexpected timeout result: {timeout_content}"
    );
    let timeout_pid = last_pid(&pid_log)?;
    wait_for_pid_exit(timeout_pid).await?;
    assert_eq!(
        call_code_success(&client, "return 'after-timeout';").await?,
        "after-timeout"
    );
    wait_for_empty_directory(&scratch).await?;

    for (source, expected_code) in [
        ("/* wit-adversarial:crash */ return null;", "worker_exited"),
        (
            "/* wit-adversarial:malformed */ return null;",
            "worker_protocol_error",
        ),
    ] {
        let result = call_code(&client, source).await?;
        assert_eq!(result.is_error, Some(true));
        assert_eq!(result.structured_content.unwrap()["code"], expected_code);
        wait_for_pid_exit(last_pid(&pid_log)?).await?;
        assert_eq!(
            call_code_success(&client, "return 'restarted';").await?,
            "restarted"
        );

        return Ok(value);
    }
    let code = envelope["error"]["code"]
        .as_str()
        .unwrap_or("code_rejected");
    let message = envelope["error"]["message"]
        .as_str()
        .unwrap_or("JavaScript execution failed");
    if code == "host_calls_limit" {
        bail!("host-call budget exhausted");
    }
    bail!("{message}")
}

const CODEMODE_PRELUDE: &str = r#"
(() => {
const __bridge = globalThis.__hostCallJson;
delete globalThis.__hostCallJson;
const __maxConcurrentHostCalls = globalThis.__maxConcurrentHostCalls;
delete globalThis.__maxConcurrentHostCalls;
let __activeHostCalls = 0;
const __hostOperation = async (operation, input) => {
  if (__activeHostCalls >= __maxConcurrentHostCalls) {
    const error = new Error("concurrent host-call budget exhausted");
    Object.defineProperties(error, {
      code: { value: "host_concurrency_limit", enumerable: true },
      operation: { value: operation, enumerable: true }
    });
    throw error;
  }
  __activeHostCalls += 1;
  try {
    const response = JSON.parse(await __bridge(operation, JSON.stringify(input)));
    if (!response.ok) {
      const error = new Error(response.error.message);
      Object.defineProperties(error, {
        code: { value: response.error.code, enumerable: true },
        operation: { value: response.error.operation, enumerable: true }
      });
      throw error;
    }
    return response.value;
  } finally {
    __activeHostCalls -= 1;
  }
};
/* TEST_HOST_CALL */
const __wit = Object.freeze({
  findRepositories: input => __hostOperation("wit_find_repositories", input),
  refs: input => __hostOperation("wit_refs", input),
  open: input => __hostOperation("wit_open", input),
  list: input => __hostOperation("wit_list", input),
  searchCode: input => __hostOperation("wit_search_code", input),
  read: input => __hostOperation("wit_read", input),
  context: input => __hostOperation("wit_context", input)
});
Object.defineProperty(globalThis, "codemode", {
  value: Object.freeze({ wit: __wit }),
  writable: false,
  configurable: false
});
const __validateFinalValue = value => {
  const seen = new Set();
  const visit = current => {
    if (current === null || typeof current === "string" || typeof current === "boolean") return;
    if (typeof current === "number") {
      if (!Number.isFinite(current)) throw new Error("final value contains a non-finite number");
      return;
    }
    if (typeof current !== "object") throw new Error("final value is not JSON-serializable");
    if (seen.has(current)) throw new Error("final value contains a cycle");
    seen.add(current);
    if (Array.isArray(current)) {
      for (let index = 0; index < current.length; index += 1) {
        if (!Object.prototype.hasOwnProperty.call(current, index)) throw new Error("final value contains an array hole");
        visit(current[index]);
      }
    } else {
      for (const key of Object.keys(current)) visit(current[key]);
    }
    seen.delete(current);
  };
  visit(value);
};
Object.defineProperty(globalThis, "__validateFinal", {
  value: __validateFinalValue,
  writable: false,
  configurable: false
});
})();
"#;
            Ok(InvocationOutcome::TimedOut) => CallToolResult::structured_error(code_error(
                "deadline_exceeded",
                "code execution deadline exceeded",
            )),
            Ok(InvocationOutcome::Cancelled { .. }) => CallToolResult::structured_error(
                code_error("cancelled", "code execution was cancelled"),
            ),
            Ok(InvocationOutcome::WorkerExited(_)) => CallToolResult::structured_error(code_error(
                "worker_exited",
                "code worker exited before returning a result",
            )),
            Ok(InvocationOutcome::ProtocolError(message)) => {
                CallToolResult::structured_error(code_error("worker_protocol_error", message))
            }
            Ok(InvocationOutcome::LimitExceeded { code, message }) => {
                CallToolResult::structured_error(code_error(code, message))
            }
            Err(error) => {
                tracing::error!(?error, "failed to start Code Mode worker");
                CallToolResult::structured_error(code_error(
                    "worker_start_failed",
                    "code worker could not be started",
                ))
            }
        }
    }
}

#[cfg(not(debug_assertions))]
fn adversarial_invocation(source: &str, limits: Limits) -> (&str, Limits, TestAction) {
    (source, limits, TestAction::Execute)
}

#[cfg(debug_assertions)]
fn adversarial_invocation(source: &str, mut limits: Limits) -> (&str, Limits, TestAction) {
    if let Some(source) = source.strip_prefix("/* wit-adversarial:crash */") {
        (source, limits, TestAction::Crash)
    } else if let Some(source) = source.strip_prefix("/* wit-adversarial:malformed */") {
        (source, limits, TestAction::EmitUnknownMessage)
    } else if let Some(source) = source.strip_prefix("/* wit-adversarial:per-call-bytes */") {
        limits.max_host_result_bytes = 1024;
        limits.max_cumulative_host_result_bytes = 4096;
        (source, limits, TestAction::Execute)
    } else if let Some(source) = source.strip_prefix("/* wit-adversarial:cumulative-bytes */") {
        limits.max_host_result_bytes = 2048;
        limits.max_cumulative_host_result_bytes = 4096;
        (source, limits, TestAction::Execute)
    } else {
        (source, limits, TestAction::Execute)
    }
}

fn code_error(code: &str, message: impl Into<String>) -> Value {
    json!({ "code": code, "message": message.into() })
}

fn host_dispatch_error(error: OperationDispatchError) -> wit_quickjs_spike::HostError {
    let message = match error.code {
        DispatchErrorCode::OperationFailed => "wit operation failed".to_string(),
        _ => error.message,
    };
    wit_quickjs_spike::HostError {
        code: serde_json::to_value(error.code)
            .ok()
            .and_then(|value| value.as_str().map(str::to_owned))
            .unwrap_or_else(|| "operation_failed".into()),
        operation: error.operation,
        message,
    }
}

fn sanitize_host_result(operation: &str, mut value: Value) -> Value {
    if operation == "wit_open"
        && let Some(cache) = value.get_mut("cache").and_then(Value::as_object_mut)
    {
        // Cache refresh diagnostics originate in git/network errors and may contain absolute
        // paths or token-shaped data. Direct MCP retains the field; untrusted Code Mode does not.
        cache.insert("last_error".into(), Value::Null);
    }
    value
}

fn code_tool_description() -> String {
    format!(
        "Execute one bounded async JavaScript function body and return its JSON value. No filesystem, network, environment, module, shell, subprocess, or arbitrary MCP APIs are available. Host-operation errors are catchable Error objects with stable code, operation, and message fields. Explicit cursors remain visible.\n\nExample:\nconst opened = await codemode.wit.open({{ repo: 'owner/repo' }});\nreturn await codemode.wit.searchCode({{ snapshot_id: opened.snapshot_id, queries: ['symbol'] }});\n\n{}",
        render_typescript_declarations()
    )
}

