                assert_eq!(transport, McpTransport::Stdio);
                assert_eq!(mode, McpMode::Code);
            }
            _ => panic!("expected mcp command"),
        }

        let defaulted = WitCli::try_parse_from(["wit", "mcp"]).expect("mcp should default stdio");
        match defaulted.command {
