const opened = await codemode.wit.open({ repo: "owner/repo" });
const found = await codemode.wit.searchCode({
  snapshot_id: opened.snapshot_id,
  queries: ["TargetSymbol"],
  max_results: 4,
  max_bytes: 16_384
});
const hit = found.items[0];
